    const e = { x: p.x - 40, y: p.y };
    add(la[i], p, e, 12, 'F.Cu');
    addVia(la[i], e);
  }
}

new_string:
// 总线末端先上廊再进排针，避免在 U7 下方横穿与 Q 扇出打架
const busToHdr = (net, busPt, jPad, layer, runY, colX) => {
  if (!net || !busPt || !jPad) return;
  L(net, [
    busPt,
    { x: busPt.x, y: runY },
    { x: colX, y: runY },
    { x: colX, y: jPad.y }
  ], 12, layer);
  addVia(net, { x: colX, y: jPad.y });
  add(net, { x: colX, y: jPad.y }, jPad, 12, 'F.Cu');
};
busToHdr(logicH, hBusEnd, jH, 'In1.Cu', 40, 3280);
busToHdr(logicL, lBusEnd, jL, 'In2.Cu', 160, 3320);

// In2：CLK 上廊（与 L→排针 runY 错开）
fanTop(clk, pw('U7', 13), jClk, 'In2.Cu', 80, 3360);
// In1：Q1（与 H→排针 runY=40 错开）
fanTop(la[1], pw('U7', 2), jQ1, 'In1.Cu', 120, 3400);
// B：Q0 / Q2 上廊 + 底廊 LOGIC_L→U7
fanTop(la[0], pw('U7', 3), jQ0, 'B.Cu', 60, 3440);
fanTop(la[2], pw('U7', 4), jQ2, 'B.Cu', 200, 3480);

// Q3..Q6 可测短桩（短水平，避开扇出逃逸线）
for (let i = 3; i < 7; i++) {
  const p = pw('U7', qPads[i]);
  if (p && la[i]) {
    const side = p.x < 3100 ? -1 : 1;
    const e = { x: p.x + side * 28, y: p.y };
    add(la[i], p, e, 12, 'F.Cu');
    addVia(la[i], e);
  }
}
